export function extend(add,lessons){
add('italian open-game','quiet','지우코 피아노 · c3/d4','e4 e5 Nf3 Nc6 Bc4 Bc5 c3 Nf6 d4 exd4 cxd4 Bb4+ Nc3','중앙이 d3형보다 일찍 열립니다.',{structure:'백 e4/d4 대 흑 d7이며 백 d폰·흑 e폰이 교환되었습니다. 백 c폰이 d4로 와 큰 중앙을 얻었습니다. 현재 e4도 남아 d4는 아직 고립폰이 아니며 흑 …d5가 해방 수입니다.',pieces:['백: c4 비숍·c3/f3 나이트가 중앙과 f7을 협력합니다. 중앙을 지키며 캐슬링·중앙 룩을 준비합니다.','흑: b4 비숍은 c3 나이트를 핀하고 f6 나이트는 e4를 공격합니다. …d5가 기물의 공간을 풉니다.']});
add('catalan','fianchetto','열린 카탈란 · 폰과 대각선','d4 Nf6 c4 e6 g3 d5 Bg2 dxc4 Nf3 Be7 O-O O-O Qc2','흑 여분 c4폰과 백 긴 대각선 압력을 비교합니다.',{structure:'백 c폰이 잡혀 흑 d폰이 c4에 남습니다. 백 d4·흑 e6가 중앙을 받치고 g2 비숍은 d5/c6/b7을 봅니다. …b5로 폰을 지키면 백 a4가 퀸측 사슬을 흔들 수 있습니다. 백 e4·흑 …c5가 중앙을 바꿉니다.',targets:['백: c4·긴 대각선 → Qc2·Bg2·나이트 → 폰 회복과 활동.','흑: 중앙·대각선 → …c5/…b5·기물 → 중앙 균형과 압력 차단.']});
add('english','fianchetto','잉글리시 · 대칭형','c4 c5 Nc3 Nc6 g3 g6 Bg2 Bg7 Nf3 Nf6 O-O O-O','역 시실리안 …e5형과 구분합니다.',{purpose:'백 c4와 흑 c5가 d5/d4를 통제하며 대칭에서 전개 템포·중앙 돌파로 차이를 만듭니다. d4/…d5 교환이 공간과 열린 파일을 결정합니다.',structure:'백 c4/g3 대 흑 c5/g6이고 d/e폰은 아직 출발 칸에 있습니다. 열린 파일은 없으며 d4/…d5 교환 뒤 공간·고립폰·반열린 파일 가능성을 다시 판단합니다.'});
add('sicilian-sveshnikov','sicilian-e5','스베시니코프 · 더블 f폰','e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 Nf6 Nc3 e5 Ndb5 d6 Bg5 a6 Na3 b5 Bxf6 gxf6','비숍 쌍과 f6/f7 더블폰이 실제로 생긴 국면입니다.',{structure:'흑 d6/e5에 f6/f7 더블폰과 반열린 g열이 생깁니다. 백 d5·d6 압박에 흑은 비숍 쌍·b5 공간·중앙 돌파로 반격합니다. …f5는 킹 안전과 e5 수비를 함께 계산합니다.',pieces:['백: c3 나이트는 d5를, a3 나이트는 c2 등 복귀 경로를 찾습니다. 남은 밝은 칸 비숍·룩은 d6를 압박합니다.','흑: f6 나이트가 교환되어 비숍 쌍이 남았습니다. b5 공간·비숍 활동·g열이 폰 약점의 보상입니다.']});
add('ruy berlin','berlin','루이 로페즈 · 교환 엔드게임','e4 e5 Nf3 Nc6 Bb5 a6 Bxc6 dxc6 O-O f6 d4 exd4 Nxd4 c5 Nb3 Qxd1 Rxd1','베를린과 달리 흑 킹은 e8이며 캐슬링 권리가 있습니다.',{purpose:'백은 비숍을 나이트와 바꿔 흑 c폰을 손상시키고 d4 교환 뒤 왕측 다수의 장기 가능성을 얻습니다. 흑은 비숍 쌍과 활동으로 보상합니다.',structure:'백 e4/f2/g2/h2 대 흑 f6/g7/h7의 왕측 다수, 흑 c5/c7 더블폰입니다. 백 d폰·흑 e폰과 퀸이 교환되었습니다. 흑의 비숍 쌍과 왕측 다수 봉쇄, 백 e4 지지와 열린 d열이 중요합니다.',pieces:['백: 중앙 나이트·d1 룩이 e4와 열린 d열을 다룹니다. 밝은 칸 비숍을 교환해 비숍 쌍은 없습니다.','흑: 비숍 쌍이 구조 손상을 보상합니다. 킹은 e8에 남아 캐슬링할 수 있으며 중앙 말로 왕측 다수를 억제합니다.'],targets:['백: 왕측 다수·c폰 → 나이트·룩·지원 폰 전진 → 패스폰 가능성.','흑: e4·중앙 → 비숍 쌍·나이트·킹 → 다수 봉쇄와 활동.']});
const ex=lessons['kings-indian'].cases.find(c=>c.label.startsWith('교환형'));
Object.assign(ex,{purpose:'백은 중앙과 퀸을 교환해 킹스 인디언의 닫힌 사슬 공격을 피하고 열린 d열의 활동을 다룹니다. 흑은 중앙 룩·나이트로 균형을 유지합니다.',ideas:['열린 d열의 룩과 진입 칸을 다툽니다.','백 d5 통제와 흑 e5 수비가 중앙 기동을 결정합니다.','퀸이 없어 킹 활동의 가치가 커지지만 체크·미전개 말의 위험은 남습니다.'],targets:['백: d5·d열 → 나이트·룩 → 봉쇄와 침투.','흑: d열·e4 → 룩·중앙 말 → 공간 균형.'],counters:['흑의 …Nc6: e5를 지키고 d4를 다툽니다. 백은 d5 거점과 룩 전개로 대응합니다.','백의 Nd5: 흑 중앙을 제한합니다. 흑은 나이트 교환과 돌파를 검토합니다.'],plans:[['퀸 없는 e4 대 e5','중앙 나이트·룩 전개','중앙 돌파는 지지 확인 후','d5·d열','활성 흑 중앙 말 교환','강한 d5 나이트 보존','중앙 봉쇄와 활동'],['e5 거점·d8 룩','퀸측 나이트·비숍 전개','조건부 …f5는 안전 확인','d열·e4','백 d5 나이트 교환 검토','중앙 수비 말 보존','균형인 퀸 없는 중앙']]});
for(const id of ['french','french-tarrasch']){const c=lessons[id].cases.find(c=>c.label.startsWith('타라시'));if(c)c.pieces=['백: d2/f3 나이트와 b5 비숍이 d5·중앙을 압박합니다. 고립폰 앞 d4가 비어 봉쇄 나이트의 경로를 찾고 중앙 룩을 전개합니다. g2 비숍의 피안케토를 현재 말 배치로 가정하지 않습니다.','흑: c5 비숍·c6 나이트는 d5 공간을 활용합니다. 중앙 룩과 왕측 기물로 활동을 유지하며 …d4 해방을 준비합니다.'];}
const qc=lessons.nimzo.cases.find(c=>c.label.includes('퀸으로'));qc.pieces=['백: c3 퀸이 되잡아 더블폰을 피했고 비숍 쌍이 남았습니다. c3 나이트는 교환되었으므로 남은 나이트 전개·e4 확장을 준비합니다.','흑: 어두운 칸 비숍이 교환되고 f6 나이트·중앙 기물이 d5/e4를 다툽니다. 백 퀸에 쓴 템포를 전개와 …c5 준비에 활용합니다.'];
for(const id of ['ruy','berlin']){const c=lessons[id].cases.find(c=>c.label.includes('루이 로페즈'));const adjust=s=>s.replaceAll('e5','e4').replaceAll('c6','c5/c7');c.plans=c.plans.map(a=>a.map(adjust));c.ideas=c.ideas.map(adjust);c.counters=c.counters.map(adjust);}
const ms=lessons.scotch.cases.find(c=>c.label.includes('미제스'));ms.plans=[['e5 공간·흑 더블 c폰','퀸측 나이트·비숍과 킹 안전','중앙 돌파는 흑 퀸 위협 확인 후','흑 중앙·약한 폰','흑의 강한 d5 나이트 교환','e5 지지 말 보존','전진폰과 기물 활동'],['c6/c7와 d5 거점','비숍·왕측 기물 전개','…d6/…d5 중앙 해방 검토','e5·중앙','백 중앙 지원 말 교환','d5 활성 나이트 보존','구조 부담을 보상한 중앙 활동']];
const dg=lessons['sicilian-dragon'].cases.find(c=>c.label.includes('같은 편'));dg.targets=['백: d6·g7 수비 비숍 → 중앙 룩·나이트·비숍 → 중앙 압박과 조건부 왕측 활동.','흑: e4/c3·퀸측 폰 → g7 비숍·중앙 나이트·c열 룩 → 중앙 균형과 파일 활동.'];
}
